function validate(input) {
  const [functions, n] = input;
  if (!Array.isArray(functions) || functions.length > 10) return 'Give at most 10 functions.';
  if (!functions.every(delay => Number.isInteger(delay) && delay >= 0 && delay <= 1000)) return 'Each function is a delay: an integer from 0 to 1000 ms.';
  if (!Number.isInteger(n) || n < 1 || n > 10) return 'n must be an integer from 1 to 10.';
  return null;
}

