function adapt(input, solve, kit) {
  const [delays, n] = input, start = Date.now();
  const times = delays.map(() => null), started = delays.map(() => false);
  const functions = delays.map((delay, i) => () => {
    if (started[i]) throw new Error(`functions[${i}] was called a second time; start each function once.`);
    started[i] = true;
    kit.trace(`functions[${i}] starts; it takes ${delay} ms`);
    return new Promise((resolve) => setTimeout(() => {
      times[i] = Date.now() - start;
      kit.trace(`functions[${i}] resolves`);
      resolve();
    }, delay));
  });
  kit.trace(`promisePool(functions, ${n}) is called`);
  const pool = solve(functions, n);
  if (!pool || typeof pool.then !== 'function') throw new Error('promisePool must return a promise.');
  return pool.then(() => {
    const total = Date.now() - start;
    kit.trace('The promise of promisePool resolves');
    return [times, total];
  });
}

