async function promisePool(functions, n) {
  // Keep the set of running promises; when it is full, wait for any one of them before starting the next.
  const running = new Set();
  for (const fn of functions) {
    if (running.size === n) await Promise.race(running);
    const promise = fn().then(() => running.delete(promise));
    running.add(promise);
  }
  await Promise.all(running);
}

