function generate(rand, size) {
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 6) : 10;
  // Small delays are multiples of 10, so several promises often resolve at the same moment.
  const functions = Array.from({ length: count }, () => (small ? 10 * Math.floor(rand() * 11) : Math.floor(rand() * 1001)));
  const n = 1 + Math.floor(rand() * (small ? 4 : 10));
  return [functions, n];
}
